// Astrolabe's $.state contract and the Spec Kit state model it holds.
// Every value is plain JSON data. Self-contained: no imports.

export type Phase = 'specify' | 'clarify' | 'plan' | 'tasks' | 'implement' | 'done' | 'abandoned'

/** A Spec Kit step a skill hint can point at; `constitution` is project level. */
export type Step = 'constitution' | 'specify' | 'clarify' | 'plan' | 'tasks' | 'implement'

export type Track = 'quick' | 'full'
export type SpecStatus = 'active' | 'done' | 'abandoned'

export type FrontMatter = { track?: Track; status?: SpecStatus }

export type Task = {
  /** The first `T\d+` token after the checkbox, when present. */
  id?: string
  text: string
  isDone: boolean
  /** 1-based line number in tasks.md. */
  line: number
  /** The heading the task sits under, such as `Phase 3: User Story 1` (045 #44). */
  story?: string
}

/** What was read from disk for one `specs/NNN-<name>/` directory. */
export type FeatureFiles = {
  dir: string
  spec?: string
  plan: boolean
  tasks?: string
  /** Open and total items across `checklists/*.md` (020b). */
  checklist?: { open: number; total: number }
  /** Files that exist but whose read failed; their text, if any, is the last one read (013). */
  unreadable?: Array<'spec.md' | 'tasks.md'>
  /** Set once the texts are compacted for the memo (spec 009), so they are not compacted again. */
  compact?: true
  /** The spec's summary for the pane (024), kept when the spec text is compacted. */
  summary?: string
  /** Not read yet: a large project reads it after the band draws (040). */
  deferred?: true
  /** Each task's line in its file (024), kept when the tasks are compacted. */
  taskLines?: number[]
  /** The tasks came from a quick spec's `## Tasks` section: there is no tasks.md (024). */
  tasksInSpec?: true
  /** The source tasks.md exceeds 2 MiB and its compact task summary is reused between edits (054 #13). */
  tasksLarge?: true
  /** The age of the spec's last change (044 #37). */
  updatedAt?: string
}

export type FeatureWarning = 'clarification-after-plan' | 'unreadable-spec' | 'unreadable-tasks' | 'loading' | 'no-spec'

export type Feature = {
  id: string
  name: string
  /** Directory name under specs/, for example `002-band-hint`. */
  dir: string
  phase: Phase
  track?: Track
  status?: SpecStatus
  done: number
  total: number
  currentTask?: { id?: string; text: string }
  warnings: FeatureWarning[]
  /** `[NEEDS CLARIFICATION` markers left in the spec (020b). */
  clarifications?: number
  /** Open and total checklist items (020b). */
  checklist?: { open: number; total: number }
  /** The age of the spec's last change (044 #37). */
  updatedAt?: string
}

export type FeatureJson =
  | { kind: 'missing' }
  | { kind: 'malformed' }
  /** `dir` is the directory name under specs/ (`002-band-hint`), or a path outside it. */
  | { kind: 'ok'; dir: string }

/** An enabled hook of `.specify/extensions.yml` (020c). */
export type ExtensionHook = { event: string; command: string; optional: boolean }

export type Snapshot = {
  /** Directory that holds `.specify/`; undefined means Spec Kit is not present. */
  root?: string
  featureJson: FeatureJson
  constitution?: string
  branch?: string
  /** The linked worktree's name when the checkout is one (023). */
  worktree?: string
  features: FeatureFiles[]
  /** Enabled Spec Kit extension hooks, read with the full snapshot (020c). */
  extensions?: ExtensionHook[]
  /** The first line of `.specify/extensions.yml` that cannot be read (054 #16). */
  extensionsError?: { line: number; reason: 'tab' | 'quote' | 'shape' }
  /** Other Spec Kit roots under the session's directory (020c). */
  otherRoots?: string[]
}

export type ActiveSource = 'feature.json' | 'branch' | 'latest'
export type ActiveWarning = 'feature-json-malformed' | 'feature-json-dangling'

export type Active = { dir: string; id: string; name: string; source: ActiveSource }

export type SkillHint = { step: Step } | { analyze: true }

/** Session-only memory kept beside the derived state. */
export type SessionMemo = {
  /** Last files read per feature dir, so a turn re-reads only what changed. */
  files: Record<string, FeatureFiles>
  /** Feature dirs for which speckit-analyze ran this session. */
  analyzed: string[]
  /** Each analyzed feature's task fingerprint when analyze ran (054 #59); a changed tasks.md clears the flag. */
  analyzedTasks?: Record<string, string>
  runningSkill?: { name: string; step: Step }
  /** Feature dirs a tool call touched during the current turn. */
  touched: string[]
  currentTask?: { dir: string; id: string; startedAt: number }
  /** The rest of the last snapshot, so a hint or one file can re-derive without reads. */
  base?: Omit<Snapshot, 'features'>
  /** This turn's drift window (reset at each main turn.complete, kept across reloads). */
  window: DriftWindow
  /** A drift alarm Claude has not yet received in its next context line. */
  driftWarning?: { dir: string; task: string }
  /** `dir:phase` keys already toasted this session. */
  toasted: string[]
  /** Whether this session's first reconcile set the phase baseline yet. */
  baselined: boolean
  /** Each feature's phase at the last reconcile, to toast moves forward (005; per session since 013). */
  baseline?: Record<string, Phase>
}

/** One main turn's work: code files edited, any Bash or Agent call, and whether drift was toasted. */
export type DriftWindow = { edits: string[]; sawShell: boolean; alarmed: boolean }

export type ConstitutionState = 'missing' | 'template' | 'ratified'

export type SpeckitState = {
  present: boolean
  root?: string
  constitution: ConstitutionState
  /** The ratified constitution's principles with their line (054 #83). */
  principles?: Array<{ name: string; line: number }>
  active?: Active
  activeWarning?: ActiveWarning
  features: Feature[]
  runningSkill?: { name: string; step: Step }
  currentTask?: { id?: string; text: string; startedAt?: number }
  isAnalyzed: boolean
  nextCommand?: string
  /** Whether this turn worked on the active feature (speckit-implement ran, or a tool touched it). */
  isWorkingOnActive?: boolean
  /** The memo version this state was derived from; an older state never overwrites a newer one. */
  memoVersion?: number
  /** When this state was last written, in `$.clock.now()` milliseconds (054 #26). */
  updatedAt?: number
  /** Other Spec Kit roots under the session's directory, by folder name (020c). */
  otherRoots?: string[]
  /** Extension hooks before and after the next command (020c). */
  nextHooks?: { before: string[]; after: string[] }
  /** The first line of `.specify/extensions.yml` that cannot be read (054 #16). */
  extensionsError?: { line: number; reason: 'tab' | 'quote' | 'shape' }
  /** The active feature's tasks, for the pane (the memo stays out of every drawing). */
  activeTasks?: Array<{ id?: string; text: string; isDone: boolean; line?: number; story?: string }>
  /** The feature the git branch names, when one does (044), to catch a stale feature.json. */
  branchFeature?: string
  /** The active spec's summary as markdown (024). */
  activeSummary?: string
  /** The active feature's files that exist, for the pane's links (024). */
  activeDocs?: Array<'spec.md' | 'plan.md' | 'tasks.md'>
}

export type PaneTab = 'specs' | 'session' | 'prs' | 'setup'

/** What the pane body shows: a tab, or the help overlay above it (066 #21). */
export type PaneView = PaneTab | 'help'

/** The /astrolabe pane's session state: the tab shown and whether it opened unasked already. */
export type PaneState = { tab: PaneTab; /** The help overlay is on, above the tab. */ help?: true; /** Specs at scale (067): the view, the open blocks and the grouping. */ view?: 'focus' | 'all'; open?: string[]; group?: 'status' | 'phase' | 'track' | 'priority'; autoOpened: boolean; filter?: string; status?: 'open' | 'all' | 'progress' | 'next' | 'done' | 'abandoned'; sort?: 'status' | 'progress' | 'name'; scroll?: { tab: PaneView; offset: number }; selectedFeature?: string; /** A task row selected in the tree (078): its key. */ selectedTask?: string; /** Specs the person opened and folded (078); the active spec is open unless it is in `closed`. */ opened?: string[]; closed?: string[]; /** Only the active spec's tasks, full height (078). */ tasksOnly?: true; /** The Session tab's folded blocks the person opened (078). */ updatesOpen?: true; logOpen?: true; turnsOpen?: true; /** The Setup groups the person opened (078). */ groupsOpen?: string[]; /** The option and the pull request the arrow keys stand on (079). */ selectedOption?: string; selectedPr?: string; summary?: { dir: string; expanded: boolean }; draft?: Record<string, string | number | boolean>; confirm?: string; confirmSelecting?: string }

export type UpdateId = 'gstack' | 'specify' | 'speckit-skills' | 'astrolabe'

/** Something with a newer version than the one installed. */
export type UpdateItem = { id: UpdateId; installed: string; latest: string }

/** What the band and pane draw about updates; `confirming` arms the skills refresh. */
export type UpdatesState = { items: UpdateItem[]; confirming?: UpdateId; running?: UpdateId }

/** One usage window as session.measure reports it. */
export type UsageReading = { kind: string; percentUsed: number; resetsAt?: string }

/** A subagent dispatch refused while usage is high, to re-dispatch after the reset. */
export type QueuedAgent = { id: string; description: string; prompt: string; subagentType?: string }

/** Usage governance (spec 008). `override` is the owner's raised stop and ceiling. */
export type UsageState = {
  readings: UsageReading[]
  history: Array<{ at: number; percent: number }>
  inFlight: number
  queue: QueuedAgent[]
  /** The owner's raised stop and ceiling, for the window it was given for (all windows when absent). */
  override?: { target: number; until: number; kind?: string }
  paused: boolean
  /** Since when work has waited on the governor: the first queued call or pause (054 #36). */
  waitingSince?: number
  /** What the governor did, newest last (021): questions, answers, resumes; at most 20. */
  log?: Array<{ at: number; text: string }>
  /** Prompts of queued subagents the person let run once at hold ("Run this one now", 017). */
  passes?: string[]
  /** The window that entered hold, held down to 75% (016). */
  held?: { kind: string; resetsAt?: string }
  /** Until when the owner let subagents through the hold, one at a time (015). */
  holdLift?: number
  /** The answer the owner gave (or the default taken) for the band now in force (015). */
  asked?: { kind: 'hold' | 'pause'; answer: string }
}

/** What `git status --porcelain=v2 --branch` said at the end of the last main turn (018). */
export type GitState = {
  branch?: string
  /** The remote's web page, from `git remote get-url origin` (054 #79). */
  remote?: string
  ahead: number
  behind: number
  changed: number
  conflicts: number
  /** Stash entries (023), from the `# stash` header. */
  stashes?: number
  /** The linked worktree's name when the checkout is one (023). */
  worktree?: string
  /** The branch's open pull request and its checks (023), from `gh`, opt-in. */
  pr?: PullRequest
  /** The upstream branch, when there is one: ahead and behind only mean something then (068 #41). */
  upstream?: string
  /** The short commit id of a detached HEAD, which has no branch page (068 #41). */
  detached?: string
  /** The main worktree's branch, when this checkout is a linked worktree (068 #41). */
  origin?: string
  /** The last CI run for the current branch, from `gh run list` (068 #41). */
  ci?: 'pass' | 'fail' | 'pending'
}

/** A pull request and the state of its checks: all passed, one failed, some still running, or none. */
export type PullRequest = { number: number; checks: 'pass' | 'fail' | 'pending' | 'none'; url?: string; /** Draft, and its labels (068 #41). */ draft?: boolean; labels?: string[] }

/** The session's numbers for the footer and the Dashboard (018); bounded, written per turn. */
export type SessionStats = {
  startedAt: number
  turns: number
  toolCalls: number
  drifts: number
  agentsRun: number
  agentsQueued: number
  model?: string
  effort?: string
  context?: { percent: number; /** Tokens in the window and its size, when the engine gave them (071). */ tokens?: number; window?: number }
  cost?: number
  git?: GitState
  /** Lines the session's tools added and removed (041 #7). */
  lines?: { added: number; removed: number }
  /** How long each ticked task took, from when it became the current one (021), at most 50. */
  taskTimes?: Array<{ dir: string; id: string; ms: number }>
  /** This week's tasks and features done, across sessions (021), copied from $.store for drawing. */
  week?: { tasks: number; features: number }
  /** Tasks done in each of the last 8 weeks, oldest first (054 #40). */
  weeksTrend?: number[]
  /** Each main turn's answer, as one line, with the feature it ran on: the last 20 (054 #92). */
  recap?: Array<{ at: number; id?: string; text: string }>
  /** One entry per main turn, the last 30: when, the spec and task it was on, and the tokens it used (078 FR-052, FR-056). */
  turnLog?: Array<{ at: number; id?: string; task?: string; tokens?: number; text?: string }>
  /** Focus mode (054 #88): Claude is told to change only the files the current task names. */
  focus?: boolean
  /** Tasks ticked on each day of this week, Monday first (046 #54). */
  weekdays?: number[]
  /** Tasks done in each recent main turn, by the turn's duration (021), at most 20. */
  turnTicks?: Array<{ ms: number; n: number }>
  /** The person's language guessed from their prompts (019): en, pt-BR, es or fr. */
  language?: string
  /** The binding window's percent per reading, at most 60 points. */
  /** The deciding window per reading, with each window and the context beside it (046 #53, #57). */
  series: Array<{ at: number; percent: number; fiveHour?: number; sevenDay?: number; context?: number }>
  /** Warnings already shown this session (022): the cost budget at 80% and 100%, the context window. */
  warned?: { cost80?: boolean; cost100?: boolean; context?: boolean }
  /** Turns in a row on the same current task without a tick, and whether that was said (054 #85). */
  spin?: { id: string; turns: number; told?: true }
  /** Subagent runs this session (046 #58): each with its feature, duration and when it started. */
  subagentRuns?: Array<{ dir: string; id: string; ms: number; at: number }>
  /** The last `gh pr view` for a branch (023): when it ran and what it found, kept five minutes. */
  prCache?: { branch: string; at: number; pr?: PullRequest; ci?: GitState['ci'] }
  /** The repository's open pull requests for the PRs tab (032), and when they were read. */
  pulls?: {
    at: number
    /** Why the last `gh pr list` gave nothing (054 #14). */
    error?: string
    rows: Array<{
      number: number
      title: string
      branch: string
      url: string
      labels: string[]
      review: 'approved' | 'changes' | 'required' | 'none'
      checks: 'pass' | 'fail' | 'pending' | 'none'
      /** Each check with its page (054 #80). */
      runs?: ReadonlyArray<{ name: string; url: string; result: 'pass' | 'fail' | 'pending' }>
      merge: string
      isDraft: boolean
      /** The head commit listed, so a merge lands only that commit (032 fix). */
      head?: string
      /** Who opened it and when, in epoch ms (052 #40). */
      author?: string
      createdAt?: number
    }>
  }
  /** The last finished feature's summary from a small model (026). */
  lastSummary?: { dir: string; text: string }
  /** Spec priorities for this project, by feature id; normal is no entry (051). */
  priorities?: Record<string, 'high' | 'normal' | 'low'>
  /** The last deep review (051): the feature, the model's findings, when. */
  lastReview?: { id: string; text: string; at: number }
  /** Milliseconds the session's work waited on the governor (054 #36). */
  waitedMs?: number
  /** Compactions this session and the context points they freed (054 #38). */
  compactions?: { n: number; freed: number }
  /** Drift alarms per feature id this session (054 #35). */
  driftsByFeature?: Record<string, number>
  /** Subagent runs per feature id this session (054 #37). */
  agentsByFeature?: Record<string, number>
  /** Task boxes ticked by edits of the main thread and of subagents this session (054 #39). */
  ticksBy?: { main: number; sub: number }
  /** How many times the advisor ran this session, and the last time (055). */
  advisor?: { runs: number; at: number; last?: { id: string; text: string; at: number } }
  /** The release gate of a repository with a plugin.json (054 #60): its version and whether that tag exists. */
  release?: { version: string; tagged: boolean; latest?: string; /** Commits since the latest tag (078). */ unreleased?: number }
  /** What `/astrolabe doctor` found, read when the Help tab opens (052 #42). */
  health?: { at: number; lines: string[] }
  /** The full text of the last toast shortened to fit the notification limit (052 #44). */
  toastDetails?: string
  /** Subagents running now, from the Agent tool call to its end (069 #43). */
  liveAgents?: Array<{ id: string; /** The engine's own id for the run, known from its first request. */ engineId?: string; brief: string; type?: string; model?: string; step?: string; contextPercent?: number; tokens?: number; startedAt: number }>
  /** Git hooks and gate scripts in the process list, read on the clock (069 #44). */
  liveGates?: Array<{ pid: number; hook?: string; chain: string[]; where: string; startedAt: number; waiting?: true }>
  /** Spec folders Claude read or edited this session, oldest first (067 #40). */
  touchedSpecs?: string[]
  /** Files each spec's plan.md names that are not there, from the reconcile's own reads (067 #33). */
  planMissing?: Record<string, string[]>
  /** Until when the step chip of the band shows brighter: a phase finished under the compact preset (065 #18). */
  phaseBrightUntil?: number
  /** The folder the session started in and the one it works in now (068 #41). */
  dirs?: { start: string; cwd: string }
  /** Skills invoked in this session, in order of first use (068 #45). */
  skills?: string[]
  /** The todo list's title and progress, from the last TodoWrite call (068 #46). */
  todo?: { title: string; done: number; total: number }
  /** The prompt cache, from the last main-thread response's usage (068 #42). */
  cache?: { at: number; tokens: number; ttlMs: number; reason?: string }
  /** Fast mode is on (068 #47). */
  fast?: boolean
  /** gstack's skills are installed under the home directory (051). */
  gstack?: boolean
  /** The features the repository's other worktrees work on (037), read after each main turn. */
  worktrees?: Array<{ name: string; branch?: string; head?: string; dir: string; id: string; featureName: string; phase: Phase; done: number; total: number; path?: string; changed?: number; merged?: true }>
  /** The last main turn's change to the active tasks, as unified-diff hunks (024). */
  tasksDiff?: { dir: string; file: 'tasks.md' | 'spec.md'; text: string; /** When the turn ended, so the diff folds after five minutes (045 #48). */ at?: number }
}

/** One answer a usage question offers; `target` is the ceiling a lifting answer sets. */
export type UsageAnswer = { value: string; label: string; target?: number }

/** What the governor asks before it holds or pauses (015). The first answer is the default. */
export type UsageQuestion = { kind: 'hold' | 'pause'; text: string; options: UsageAnswer[]; fallback: string }

/** The open question the `astrolabe-usage` pane draws, with when its default goes ahead. */
export type AskState = { question?: UsageQuestion; deadline?: number }

/** One styled piece of the footer statusline drew (070). */
export type FooterRun = { text: string; fg?: string; bg?: string; bold?: true; dim?: true; underline?: true; href?: string }

/** The footer statusline draws and where it came from (070): its own state key, so a new render does not copy the session's stats. */
export type FooterState = {
  render?: { at: number; columns: number; lines: FooterRun[][] }
  health?: { source: 'statusline' | 'native'; reason?: string; version?: string; commit?: string; /** How the renderer answered: its runs object, or ANSI text from a copy that does not know runs (076). */ format?: 'runs' | 'ansi'; contract?: number
    /** What the footer was asked to be and what the copy resolved (082): the mode, the omit list, the flavor asked for, and `--print-config`'s answer when the copy has one. */
    embed?: { mode: 'live' | 'passive'; omit: string; asked: string; config?: { flavor: string; flavorSource?: string; glyphs?: string; separator?: string; passive?: boolean; omitted: string[] } }
  }
}

declare module 'claude-code' {
  interface PluginState {
    astrolabe: { speckit: SpeckitState; memo: SessionMemo; pane: PaneState; updates: UpdatesState; usage: UsageState; ask: AskState; session: SessionStats; footer: FooterState }
  }
}
